INSERT INTO `oc_modification` (`modification_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(1, 'Local copy OCMOD', 'isensealabs_quickfix_ocmod', 'iSenseLabs', '1.3', 'http://isenselabs.com', '<modification>\r\n    <name>Local copy OCMOD</name>\r\n	<version>1.3</version>\r\n	<link>http://isenselabs.com</link>\r\n	<author>iSenseLabs</author>\r\n	<code>isensealabs_quickfix_ocmod</code>\r\n\r\n	<file path=\"admin/controller/extension/installer.php\">\r\n		<operation error=\"skip\">\r\n			<search ><![CDATA[\'url\'  => str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/installer/ftp\', \'token=\' . $this->session->data[\'token\'],]]></search>\r\n			<add position=\"replace\"><![CDATA[\'url\'  => str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/installer/localcopy\', \'token=\' . $this->session->data[\'token\'],]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[public function unzip() {]]></search>\r\n			<add position=\"before\"><![CDATA[			\r\n	public function localcopy() {\r\n		$this->load->language(\'extension/installer\');\r\n\r\n		$json = array();\r\n\r\n		if (!$this->user->hasPermission(\'modify\', \'extension/installer\')) {\r\n			$json[\'error\'] = $this->language->get(\'error_permission\');\r\n		}\r\n\r\n		if (VERSION == \'2.0.0.0\') {\r\n		    $directory = DIR_DOWNLOAD  . str_replace(array(\'../\', \'..\\\\\', \'..\'), \'\', $this->request->post[\'path\']) . \'/upload/\';\r\n		} else {\r\n		    $directory = DIR_UPLOAD  . str_replace(array(\'../\', \'..\\\\\', \'..\'), \'\', $this->request->post[\'path\']) . \'/upload/\';\r\n		}\r\n\r\n		if (!is_dir($directory)) {\r\n			$json[\'error\'] = $this->language->get(\'error_directory\');\r\n		}\r\n\r\n		if (!$json) {\r\n			// Get a list of files ready to upload\r\n			$files = array();\r\n\r\n			$path = array($directory . \'*\');\r\n\r\n			while (count($path) != 0) {\r\n				$next = array_shift($path);\r\n\r\n				foreach (glob($next) as $file) {\r\n					if (is_dir($file)) {\r\n						$path[] = $file . \'/*\';\r\n					}\r\n\r\n					$files[] = $file;\r\n				}\r\n			}\r\n\r\n			$root = dirname(DIR_APPLICATION).\'/\';\r\n\r\n			foreach ($files as $file) {\r\n				// Upload everything in the upload directory\r\n				$destination = substr($file, strlen($directory));\r\n\r\n				// Update from newer OpenCart versions:\r\n				if (substr($destination, 0, 5) == \'admin\') {\r\n					$destination = DIR_APPLICATION . substr($destination, 5);\r\n				} else if (substr($destination, 0, 7) == \'catalog\') {\r\n					$destination = DIR_CATALOG . substr($destination, 7);\r\n				} else if (substr($destination, 0, 5) == \'image\') {\r\n					$destination = DIR_IMAGE . substr($destination, 5);\r\n				} else if (substr($destination, 0, 6) == \'system\') {\r\n					$destination = DIR_SYSTEM . substr($destination, 6);\r\n				} else {\r\n					$destination = $root.$destination;\r\n				}\r\n\r\n				if (is_dir($file)) {\r\n					if (!file_exists($destination)) {\r\n						if (!mkdir($destination)) {\r\n							$json[\'error\'] = sprintf($this->language->get(\'error_ftp_directory\'), $destination);\r\n						}\r\n					}\r\n				}\r\n\r\n				if (is_file($file)) {\r\n					if (!copy($file, $destination)) {\r\n						$json[\'error\'] = sprintf($this->language->get(\'error_ftp_file\'), $file);\r\n					}\r\n				}\r\n			}\r\n		}\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}]]></add>\r\n		</operation>\r\n	</file>	\r\n</modification>\r\n', 1, '2022-02-26 19:12:52'),
(2, 'DEV-OPENCART.COM — SVG Support', 'dev_opencart_com_svg_support', 'DEV-OPENCART.COM', '4.2.2', 'https://dev-opencart.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification>\r\n  <name>DEV-OPENCART.COM — SVG Support</name>\r\n<version>4.2.2</version>\r\n<link>https://dev-opencart.com</link>\r\n<author>DEV-OPENCART.COM</author>\r\n<code>dev_opencart_com_svg_support</code>\r\n	\r\n  <file path=\"admin/model/tool/image.php\">\r\n	<operation error=\"skip\">\r\n      <search><![CDATA[IMAGETYPE_GIF)))]]></search>\r\n      <add position=\"replace\"><![CDATA[IMAGETYPE_GIF)) && $image_type)]]></add>\r\n    </operation>\r\n    <operation error=\"skip\">\r\n      <search><![CDATA[$this->request->server[\'HTTPS\']]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n		if (mime_content_type(DIR_IMAGE . $image_old) != \'image/svg+xml\' && in_array($extension, array(\'svg\', \'SVG\'))) {\r\n			$dom = new DOMDocument;\r\n			$dom->loadXML(file_get_contents(DIR_IMAGE . $image_old));\r\n\r\n			if ($dom) {\r\n				$svg = simplexml_import_dom($dom);\r\n			}\r\n		} elseif (mime_content_type(DIR_IMAGE . $image_old) == \'image/svg+xml\') {\r\n			$svg = simplexml_load_file(DIR_IMAGE . $image_old);\r\n		}\r\n\r\n		if (isset($svg)) {\r\n			$svg[\'width\'] = $width;\r\n			$svg[\'height\'] = $height;\r\n\r\n			$svg->asXML(DIR_IMAGE . $image_new);\r\n		}\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n  \r\n  <file path=\"catalog/model/tool/image.php\">\r\n	<operation error=\"skip\">\r\n      <search><![CDATA[IMAGETYPE_GIF)))]]></search>\r\n      <add position=\"replace\"><![CDATA[IMAGETYPE_GIF)) && $image_type)]]></add>\r\n    </operation>\r\n    <operation error=\"skip\">\r\n      <search><![CDATA[$this->request->server[\'HTTPS\']]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n		if (mime_content_type(DIR_IMAGE . $image_old) != \'image/svg+xml\' && in_array($extension, array(\'svg\', \'SVG\'))) {\r\n			$dom = new DOMDocument;\r\n			$dom->loadXML(file_get_contents(DIR_IMAGE . $image_old));\r\n\r\n			if ($dom) {\r\n				$svg = simplexml_import_dom($dom);\r\n			}\r\n		} elseif (mime_content_type(DIR_IMAGE . $image_old) == \'image/svg+xml\') {\r\n			$svg = simplexml_load_file(DIR_IMAGE . $image_old);\r\n		}\r\n\r\n		if (isset($svg)) {\r\n			if ($svg[\'width\'] && $svg[\'height\']) {\r\n				$width_orig = (string)$svg[\'width\'];\r\n				$height_orig = (string)$svg[\'height\'];\r\n\r\n				if (is_numeric($width_orig) && is_numeric($height_orig)) {\r\n					$width_orig = (string)$svg[\'width\'];\r\n					$height_orig = (string)$svg[\'height\'];\r\n				} elseif (substr($width_orig, -2) == \'px\' && substr($height_orig, -2) == \'px\') {\r\n					$width_orig = str_replace(\'px\', \'\', $width_orig);\r\n					$height_orig = str_replace(\'px\', \'\', $height_orig);\r\n\r\n					if (!is_numeric($width_orig) && !is_numeric($height_orig)) {\r\n						$width_orig = \'\';\r\n						$height_orig = \'\';\r\n					}\r\n				}\r\n			} elseif ($svg[\'viewBox\']) {\r\n				$viewbox = explode(\' \', $svg[\'viewBox\']);\r\n\r\n				$height_orig = array_pop($viewbox);\r\n				$width_orig = array_pop($viewbox);\r\n			} else {\r\n				$width_orig = \'\';\r\n				$height_orig = \'\';\r\n			}\r\n\r\n			if (($width_orig && $height_orig) && ($width_orig != $width || $height_orig != $height)) {\r\n				$scale_w = $width / $width_orig;\r\n				$scale_h = $height / $height_orig;\r\n\r\n				$scale = min($scale_w, $scale_h);\r\n\r\n				$new_width = (int)($width_orig * $scale);\r\n				$new_height = (int)($height_orig * $scale);\r\n\r\n				$svg[\'width\'] = $new_width;\r\n				$svg[\'height\'] = $new_height;\r\n\r\n				$svg->asXML(DIR_IMAGE . $image_new);\r\n			} else {\r\n				$svg[\'width\'] = $width;\r\n				$svg[\'height\'] = $height;\r\n\r\n				$svg->asXML(DIR_IMAGE . $image_new);\r\n			}\r\n		}\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n  \r\n  <file path=\"admin/controller/common/filemanager.php\">\r\n	<operation error=\"skip\">\r\n      <search><![CDATA[{jpg,jpeg,png,gif,JPG,JPEG,PNG,GIF}]]></search>\r\n      <add position=\"replace\"><![CDATA[{jpg,jpeg,png,gif,svg,JPG,JPEG,PNG,GIF,SVG}]]></add>\r\n    </operation>\r\n	<operation error=\"skip\">\r\n      <search><![CDATA[\r\n						\'png\'\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n						\'svg\',\r\n      ]]></add>\r\n    </operation>\r\n	<operation error=\"skip\">\r\n      <search><![CDATA[\r\n						\'image/gif\'\r\n      ]]></search>\r\n      <add position=\"before\"><![CDATA[\r\n						\'image/svg+xml\',\r\n      ]]></add>\r\n    </operation>\r\n  </file>\r\n</modification>', 0, '2022-02-26 19:13:15'),
(9, 'Brainy Filter', 'brainyfilter', 'Giant Leap Lab', 'Ultimate 5.1.2 OC2.3', '', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>  \n   <id>Brainy Filter</id>\n   <name>Brainy Filter</name>\n   <code>brainyfilter</code>\n   <version>Ultimate 5.1.2 OC2.3</version>\n   <author>Giant Leap Lab</author>\n   \n   <file path=\"catalog/controller/product/*.php\">\n       <operation>\n           <search><![CDATA[$this->model_catalog_product->getProducts($filter_data)]]></search>\n           <add position=\"before\"><![CDATA[            $filter_data[\'filter_bfilter\'] = true;]]></add>\n       </operation>\n       <operation>\n           <search><![CDATA[= $this->model_catalog_product->getTotalProducts($filter_data)]]></search>\n           <add position=\"before\"><![CDATA[            $filter_data[\'filter_bfilter\'] = true;]]></add>\n       </operation>\n   </file>\n   \n   <file path=\"catalog/controller/product/category.php\">\n	  <operation>\n			<search><![CDATA[$category_info = $this->model_catalog_category->getCategory($category_id);]]></search>\n            <add position=\"after\"><![CDATA[\n                /* Brainy Filter (brainyfilter.xml) - Start ->*/\n                if (!$category_info) {\n                    $this->load->language(\'extension/module/brainyfilter\');\n                    $category_info = array(\n                        \'name\' => $this->language->get(\'text_bf_page_title\'),\n                        \'description\' => \'\',\n                        \'meta_description\' => \'\',\n                        \'meta_keyword\' => \'\',\n                        \'meta_title\' => $this->language->get(\'text_bf_page_title\'),\n                        \'image\' => \'\',\n                    );\n                    $this->request->get[\'path\'] = 0;\n                    $showCategories = false;\n                    $route = \'extension/module/brainyfilter/filter\';\n                    $path  = \'\';\n                } else {\n                    $route = \'product/category\';\n                    $path  = \'path=\' . $this->request->get[\'path\'];\n                    $showCategories = true;\n                }\n                /* Brainy Filter (brainyfilter.xml) - End ->*/\n                ]]>\n			</add>\n	  </operation>\n	  <operation>\n			<search><![CDATA[$results = $this->model_catalog_category->getCategories($category_id);]]></search>\n            <add position=\"replace\"><![CDATA[\n                /* Brainy Filter (brainyfilter.xml) - Start ->*/\n                if ($showCategories) {\n                $results = $this->model_catalog_category->getCategories($category_id);\n                } else {\n                    $results = array();\n                }\n                /* Brainy Filter (brainyfilter.xml) - End ->*/\n            ]]>\n			</add>\n	  </operation>\n	  <operation>\n			<search regex=\"true\"><![CDATA[/\\\'product\\/category\\\', \\\'path\\=\\\' \\. \\$this\\-\\>request\\-\\>get\\[\\\'path\\\'\\]/]]></search>\n            <add position=\"replace\"><![CDATA[$route, $path]]>\n			</add>\n	  </operation>\n        <operation>\n            <search><![CDATA[if ($page == 1) {]]></search>\n            <add position=\"before\">\n                <![CDATA[\n                /* Brainy Filter (brainyfilter.xml) - Start ->*/\n                if (isset($category_info[\'category_id\'])) {\n                /* Brainy Filter (brainyfilter.xml) - End ->*/]]>\n            </add>\n        </operation>\n        <operation>\n            <search><![CDATA[if ($limit && ceil($product_total / $limit) > $page) {]]></search>\n            <add position=\"after\" offset=\"2\">\n                <![CDATA[\n                /* Brainy Filter (brainyfilter.xml) - Start ->*/\n                }\n                /* Brainy Filter (brainyfilter.xml) - End ->*/]]>\n            </add>\n        </operation>\n   </file>\n   \n   <file path=\"catalog/controller/product/special.php\">\n        <operation>\n            <search><![CDATA[$product_total = $this->model_catalog_product->getTotalProductSpecials();]]></search>\n            <add position=\"replace\"><![CDATA[\n                $filter_data[\'filter_bfilter\'] = true;\n                $filter_data[\'filter_specials_only\'] = true;\n                $product_total = $this->model_catalog_product->getTotalProducts($filter_data);\n            ]]></add>\n        </operation>\n        <operation>\n            <search><![CDATA[$results = $this->model_catalog_product->getProductSpecials($filter_data);]]></search>\n            <add position=\"replace\"><![CDATA[\n                $results = $this->model_catalog_product->getProducts($filter_data);\n            ]]></add>\n        </operation>\n   </file>\n   \n   <file path=\"catalog/controller/product/search.php\">\n       <operation>\n           <search><![CDATA[if (isset($this->request->get[\'search\']) || isset($this->request->get[\'tag\'])) {]]></search>\n           <add position=\"replace\"><![CDATA[\n                    /* Brainy Filter (brainyfilter.xml) - Start ->*/\n                    /* Show product list in any case */\n					if (true) {\n                    /* Brainy Filter (brainyfilter.xml) - End ->*/\n                ]]>\n           </add>\n       </operation>\n   </file>\n   \n    <file path=\"catalog/model/catalog/product.php\">\n        <operation>\n            <search><![CDATA[public function getProducts($data = array()) {]]></search>\n            <add>\n                <![CDATA[\n    /**\n     * Custom getProducts() method added by Brainy Filter extension\n     */\n    public function getProducts($data = array()) \n    {\n        if (!isset($data[\'filter_bfilter\'])) {\n            return $this->getProductsOriginal($data);\n        }\n        $settings = $this->config->get(\'brainyfilter_layout_basic\');\n        if (isset($settings[\'global\'][\'subcategories_fix\']) && $settings[\'global\'][\'subcategories_fix\']) {\n            $data[\'filter_sub_category\'] = true;\n        }\n        $this->load->model(\'extension/module/brainyfilter\');\n        $model = new ModelExtensionModuleBrainyFilter($this->registry);\n        $model->setData($data);\n        $sql = $model->prepareQueryForCategory();\n        $query = $this->db->query($sql);\n\n        $product_data = array();\n		foreach ($query->rows as $result) {\n			$product_data[$result[\'product_id\']] = $this->getProduct($result[\'product_id\']);\n		}\n\n		return $product_data;\n    }\n    \n    /** \n     * It is the original getProducts() method, which was renamed by Brainy Filter modification.\n     * A custom getProduct() method was added instead. \n     * Disable the Brainy Filter OCMOD modification in order to reset the method.\n     * Note: disabling of Brainy Filter modification will break the work of Brainy Filter extension.\n     */\n     public function getProductsOriginal($data = array()) { ]]>\n            </add>\n        </operation>\n        \n        <operation>\n            <search><![CDATA[public function getTotalProducts($data = array()) {]]></search>\n            <add>\n                <![CDATA[\n    /**\n     * Custom getTotalProducts() method added by Brainy Filter extension\n     */\n    public function getTotalProducts($data = array())\n    {\n        if (!isset($data[\'filter_bfilter\'])) {\n            return $this->getTotalProductsOriginal($data);\n        }\n        $settings = $this->config->get(\'brainyfilter_layout_basic\');\n        if (isset($settings[\'global\'][\'subcategories_fix\']) && $settings[\'global\'][\'subcategories_fix\']) {\n            $data[\'filter_sub_category\'] = true;\n        }\n        $this->load->model(\'extension/module/brainyfilter\');\n        $model = new ModelExtensionModuleBrainyFilter($this->registry);\n        $model->setData($data);\n        $sql = $model->prepareQueryForTotal();\n		$query = $this->db->query($sql);\n\n		return $query->row[\'total\'];\n    }\n    \n    /** \n     * It is the original getTotalProducts() method, which was renamed by Brainy Filter modification.\n     * A custom getTotalProducts() method was added instead. \n     * Disable the Brainy Filter OCMOD modification in order to reset the method.\n     * Note: disabling of Brainy Filter modification will break the work of Brainy Filter extension.\n     */\n     public function getTotalProductsOriginal($data = array()) { ]]>\n            </add>\n        </operation>\n    </file>\n    <file path=\"catalog/model/checkout/order.php\">\n        <operation>\n            <search><![CDATA[$this->cache->delete(\'product\');]]></search>\n            <add position=\"before\"><![CDATA[\n                require_once \'admin/model/extension/module/brainyfilter.php\';\n                $bfModel = new ModelExtensionModuleBrainyFilter($this->registry);\n                $prodIds = array();\n                $res = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"order_product WHERE order_id = \'\" . (int)$order_id . \"\'\");\n                foreach($res->rows as $prod) {\n                    $prodIds[] = $prod[\'product_id\'];\n                }\n                $bfModel->updateStockCache($prodIds);\n            ]]></add>\n        </operation>\n    </file>\n</modification>', 1, '2025-08-29 10:02:06'),
(4, 'Custom Quick Checkout', 'customquickcheckout', 'opencart2x', '6.4.0.0', 'https://opencart2x.ru', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n	<name>Custom Quick Checkout</name>\n	<code>customquickcheckout</code>\n	<version>6.4.0.0</version>\n	<author>opencart2x</author>\n	<link>https://opencart2x.ru</link>\n	\n    <file path=\"catalog/controller/checkout/checkout.php\">\n        <operation error=\"skip\">\n            <search ><![CDATA[if (file_exists(DIR_TEMPLATE . $this->config->get(\'config_template\') . \'/template/checkout/checkout.tpl\')) {]]></search>\n			<add position=\"replace\" offset=\"4\"><![CDATA[\n			// a_vqmod_d_quickcheckout.xml\n			if($this->config->get(\'d_quickcheckout_status\')){\n				$template = \'d_quickcheckout\';\n			}else{\n				$template = \'checkout\';\n			}\n			\n			if (file_exists(DIR_TEMPLATE . $this->config->get(\'config_template\') . \'/template/checkout/\'.$template.\'.tpl\')) {\n				$template = $this->config->get(\'config_template\') . \'/template/checkout/\'.$template.\'.tpl\';\n			} else {\n				$template = \'default/template/checkout/\'.$template.\'.tpl\';\n			}\n			$this->response->setOutput($this->load->view($template, $data));]]>\n			</add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/checkout/checkout.php\">\n        <operation error=\"skip\">\n			<search><![CDATA[$this->response->setOutput($this->load->view(\'checkout/checkout\', $data));]]></search>\n			<add position=\"replace\"><![CDATA[\n			// a_vqmod_d_quickcheckout.xml\n			if($this->config->get(\'d_quickcheckout_status\')){\n				$template = \'d_quickcheckout\';\n			}else{\n				$template = \'checkout\';\n			}\n			\n			$this->response->setOutput($this->load->view(\'checkout/\'.$template, $data));]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/checkout/checkout.php\">\n		<operation>\n			<search ><![CDATA[$data[\'header\'] = $this->load->controller(\'common/header\');]]></search>\n			<add position=\"before\"><![CDATA[\n		if($this->config->get(\'d_quickcheckout_status\')){\n			$data[\'d_quickcheckout\'] = $this->load->controller(\'extension/module/d_quickcheckout\');\n		}\n		]]></add>\n		</operation>\n    </file>\n    <file path=\"system/library/cart/tax.php\">\n		<operation error=\"skip\">\n			<search ><![CDATA[final class Tax {]]></search>\n			<add position=\"after\"><![CDATA[\n	// a_vqmod_d_quickcheckout.xml\n	public function clearRates(){\n		$this->tax_rates = array();\n	}\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"system/library/tax.php\">\n		<operation error=\"skip\">\n			<search ><![CDATA[final class Tax {]]></search>\n			<add position=\"after\"><![CDATA[\n	// a_vqmod_d_quickcheckout.xml\n	public function clearRates(){\n		$this->tax_rates = array();\n	}\n			]]></add>\n		</operation>\n	</file>	\n</modification>', 0, '2022-03-09 11:06:09'),
(6, 'EasyPhoto 3.1', 'EasyPhoto', 'prut.n.v@gmail.com', '3.1', 'https://microdata.pro', '<modification>\n	<name>EasyPhoto 3.1</name>\n	<code>EasyPhoto</code>\n	<version>3.1</version>\n	<author>prut.n.v@gmail.com</author>\n	<link><![CDATA[https://microdata.pro]]></link>\n\n  <file path=\"admin/view/template/common/header.tpl\">\n    <operation>\n        <search><![CDATA[<script type=\"text/javascript\" src=\"view/javascript/bootstrap/js/bootstrap.min.js\"></script>]]></search>\n				<add position=\"before\"><![CDATA[\n					<script src=\"https://ajax.googleapis.com/ajax/libs/jqueryui/1.11.4/jquery-ui.min.js\"></script>\n					<script src=\"https://cdnjs.cloudflare.com/ajax/libs/bootstrap-switch/3.3.2/js/bootstrap-switch.min.js\"></script>\n					<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/bootstrap-switch/3.3.2/css/bootstrap2/bootstrap-switch.min.css\" />\n				]]></add>\n    </operation>\n	</file>\n\n  <file path=\"admin/controller/catalog/product.php\">\n    <operation>\n        <search><![CDATA[$this->load->model(\'design/layout\');]]></search>\n        <add position=\"before\"><![CDATA[$data[\'easyphoto_form\'] = $this->load->controller(\'module/easyphoto/getForm\', $data);]]></add>\n    </operation>\n	</file>\n\n	<file path=\"admin/model/catalog/product.php\">\n    <operation>\n        <search index=\"0\"><![CDATA[if (isset($data[\'product_image\'])) {]]></search>\n        <add position=\"replace\"><![CDATA[\n					/* ++ easyphoto */\n					if(!isset($data[\'copy_flag\'])){\n						if (isset($data[\'image\'])) {\n							$easyphoto_data = array(\'image\' => $data[\'image\'], \'product_id\' => $product_id);\n							$data[\'image\'] = $this->load->controller(\'module/easyphoto/resize_rename\', $easyphoto_data);\n							$this->db->query(\"UPDATE \" . DB_PREFIX . \"product SET image = \'\" . $this->db->escape($data[\'image\']) . \"\' WHERE product_id = \'\" . (int)$product_id . \"\'\");\n						}\n						if (isset($data[\'product_image\'])) {\n							foreach ($data[\'product_image\'] as $product_image) {\n								$easyphoto_data = array(\'image\' => $product_image[\'image\'], \'product_id\' => $product_id);\n								$product_image[\'image\'] = $this->load->controller(\'module/easyphoto/resize_rename\', $easyphoto_data);\n								$this->db->query(\"INSERT INTO \" . DB_PREFIX . \"product_image SET product_id = \'\" . (int)$product_id . \"\', image = \'\" . $this->db->escape($product_image[\'image\']) . \"\', sort_order = \'\" . (int)$product_image[\'sort_order\'] . \"\'\");\n							}\n						}\n					}else{\n					/* -- easyphoto */\n	       ]]></add>\n    </operation>\n		<operation>\n        <search><![CDATA[$this->addProduct($data);]]></search>\n        <add position=\"before\"><![CDATA[\n					/* ++ easyphoto */\n					$data[\'copy_flag\'] = true;\n					/* -- easyphoto */\n	       ]]></add>\n    </operation>\n		<operation>\n        <search><![CDATA[$data[\'product_image\'] = $this->getProductImages($product_id);]]></search>\n        <add position=\"replace\"><![CDATA[\n					/* ++ easyphoto */\n					//$data[\'product_image\'] = $this->getProductImages($product_id);\n					$data[\'product_image\'] = array();\n					/* -- easyphoto */\n	       ]]></add>\n    </operation>\n	</file>\n\n	<file path=\"admin/view/template/catalog/product_form.tpl\">\n    <operation error=\"skip\">\n        <search><![CDATA[<li><a href=\"#tab-data\" data-toggle=\"tab\"><?php echo $tab_data; ?></a></li>]]></search>\n        <add position=\"before\"><![CDATA[<li><a href=\"#tab-easyphoto\" data-toggle=\"tab\">Easyphoto</a></li>]]></add>\n   </operation>\n\n    <operation error=\"skip\">\n        <search><![CDATA[<div class=\"tab-pane\" id=\"tab-data\">]]></search>\n        <add position=\"before\"><![CDATA[\n					<?php echo $easyphoto_form; ?>\n	      ]]></add>\n    </operation>\n	</file>>\n</modification>\n', 0, '2022-03-16 13:40:56'),
(7, 'DEV-OPENCART.COM — Простое оформление заказа', 'dev_opencart_com_just_oform_zakaz', 'DEV-OPENCART.COM', '1', 'https://dev-opencart.com', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n	<name>DEV-OPENCART.COM — Простое оформление заказа</name>\n  <version>1</version>\n  <link>https://dev-opencart.com</link>\n  <author>DEV-OPENCART.COM</author>\n  <code>dev_opencart_com_just_oform_zakaz</code>\n\n	<file path=\"catalog/controller/checkout/checkout.php\">\n		<operation>\n		<search>\n			<![CDATA[\n				public function index() {\n			]]>\n		</search>\n		<add position=\"after\">\n			<![CDATA[		\n				$this->response->redirect($this->url->link(\'checkout/custom\'));\n			]]>\n		</add>\n		</operation>\n	</file> \n\n	<file path=\"catalog/controller/checkout/cart.php\">\n		<operation>\n		<search>\n			<![CDATA[\n				public function index() {\n			]]>\n		</search>\n		<add position=\"after\">\n			<![CDATA[		\n				$this->response->redirect($this->url->link(\'checkout/custom\'));\n			]]>\n		</add>\n		</operation>\n	</file> \n\n	<file path=\"admin/controller/common/column_left.php\">\n		<operation>\n			<search>\n				<![CDATA[\n					if ($this->user->hasPermission(\'access\', \'extension/modification\')) {\n				]]>\n			</search>\n			<add position=\"before\">\n				<![CDATA[		\n					if ($this->user->hasPermission(\'access\', \'extension/module/custom\')) {		\n						$extension[] = array(\n							\'name\'	   => $this->language->get(\'text_module_custom\'),\n							\'href\'     => $this->url->link(\'extension/module/custom\', \'token=\' . $this->session->data[\'token\'], true),\n							\'children\' => array()\n						);\n					}\n				]]>\n			</add>\n		</operation>\n	</file> \n	\n	<file path=\"admin/language/ru-ru/common/column_left.php\">\n		<operation>\n			<search>\n				<![CDATA[\n					$_[\'text_modification\']\n				]]>\n			</search>\n			<add position=\"before\">\n				<![CDATA[		\n					$_[\'text_module_custom\'] = \'Оформление заказа\';\n				]]>\n			</add>\n		</operation>\n	</file>\n	\n	<file path=\"admin/language/en-gb/common/column_left.php\">\n		<operation>\n			<search>\n				<![CDATA[\n					$_[\'text_modification\']\n				]]>\n			</search>\n			<add position=\"before\">\n				<![CDATA[		\n					$_[\'text_module_custom\'] = \'Custom Checkout\';\n				]]>\n			</add>\n		</operation>\n	</file>\n\n</modification>\n', 0, '2022-03-20 16:34:32');
